    if 'yillar' in _o:
        _g = [(y, md) for y, md in sorted(_o['yillar'].items()) if _dt.date(y, *map(int, md.split('-'))) >= _bugun]
        _o['tarih'] = (_g[0] if _g else sorted(_o['yillar'].items())[-1])[1]
